import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.copy(config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // Layout constants
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const CARD_GAP = 0.25;
  const TOTAL_W = 5.0;

  // Color palette (hex values)
  const COLORS = {
    cardGradTop: 0x191921,
    cardGradBot: 0x121218,
    border: 0x26262f,
    accentRed: 0xff2a38,
    paper: 0xe8ecf2,
    seatMetal: 0x2a2a32
  };

  // Card data
  const CARD_DATA = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  const cards = [];
  const timelines = [];

  // Create card meshes
  CARD_DATA.forEach((cardData, idx) => {
    const xPos = -TOTAL_W / 2 + idx * (CARD_W + CARD_GAP) + CARD_W / 2;
    const card = createCardMesh(cardData, {
      position: new THREE.Vector3(xPos, 0, 0),
      width: CARD_W,
      height: CARD_H,
      colors: COLORS,
      ctx
    });

    group.add(card);
    cards.push(card);
  });

  // Entry animation: stagger-cards with fade-up
  cards.forEach((card, idx) => {
    // Set initial state
    card.position.y = 0.2;
    card.traverse(node => {
      if (node.material && typeof node.material.opacity === 'number') {
        node.material.transparent = true;
        node.material.opacity = 0;
      }
    });

    // Animate entry
    const delay = idx * 0.08;
    const tl = gsap.timeline();

    // Position fade-up
    tl.to(card.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay
    }, 0);

    // Opacity fade-in
    card.traverse(node => {
      if (node.material && typeof node.material.opacity === 'number') {
        tl.to(node.material, {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        }, delay);
      }
    });

    timelines.push(tl);
  });

  // Store original positions for hover
  cards.forEach((card, idx) => {
    card.userData.cardIndex = idx;
    card.userData.originalPosition = card.position.clone();
    card.userData.hoverTimeline = null;
  });

  // Hover handlers
  group.userData.handlers = {};

  group.userData.handlers.onCardHover = (cardIndex, isHovered) => {
    if (cardIndex < 0 || cardIndex >= cards.length) return;

    const card = cards[cardIndex];
    const origPos = card.userData.originalPosition;

    // Kill existing hover timeline
    if (card.userData.hoverTimeline) {
      card.userData.hoverTimeline.kill();
    }

    card.userData.hoverTimeline = gsap.timeline();

    if (isHovered) {
      // Lift with translateZ
      card.userData.hoverTimeline.to(card.position, {
        y: origPos.y + 0.06,
        z: origPos.z + 0.12,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);

      // Brighten glyph emissive
      card.traverse(node => {
        if (node.userData.isGlyph && node.material) {
          gsap.to(node.material, {
            emissiveIntensity: 2.2,
            duration: 0.18,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
        }
      });
    } else {
      // Return to original
      card.userData.hoverTimeline.to(card.position, {
        y: origPos.y,
        z: origPos.z,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);

      // Dim glyph emissive
      card.traverse(node => {
        if (node.userData.isGlyph && node.material) {
          gsap.to(node.material, {
            emissiveIntensity: 1.6,
            duration: 0.18,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
        }
      });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    cards.forEach(card => {
      if (card.userData.hoverTimeline) {
        card.userData.hoverTimeline.kill();
      }
    });

    group.traverse(node => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(m => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return group;
}

function createCardMesh(data, opts) {
  const { position, width, height, colors, ctx } = opts;

  const container = new THREE.Group();
  container.position.copy(position);

  // Card background plate
  const bgGeo = new THREE.BoxGeometry(width, height, 0.02);
  const bgMat = new THREE.MeshStandardNodeMaterial({
    color: colors.cardGradTop,
    metalness: 0.25,
    roughness: 0.6,
    clearcoat: 0.15,
    emissive: 0x000000,
    transparent: true,
    opacity: 1.0
  });

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  container.add(bgMesh);

  // Icon seat disc (machined metal)
  const seatRadius = 0.2;
  const seatDepth = 0.05;
  const seatGeo = new THREE.CylinderGeometry(seatRadius, seatRadius, seatDepth, 32);
  const seatMat = new THREE.MeshStandardNodeMaterial({
    color: colors.seatMetal,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    emissive: 0x000000,
    transparent: true,
    opacity: 1.0
  });

  const seatMesh = new THREE.Mesh(seatGeo, seatMat);
  seatMesh.position.set(0, height / 2 - 0.4, 0.015);
  container.add(seatMesh);

  // Icon glyph (mono number in accent red)
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      const glyphMesh = ctx.fontAtlas.createTextMesh({
        text: data.icon,
        font: 'JetBrains Mono',
        size: 20,
        weight: 700,
        color: colors.accentRed,
        emissive: colors.accentRed,
        emissiveIntensity: 1.6
      });

      if (glyphMesh) {
        glyphMesh.position.set(0, height / 2 - 0.4, 0.03);
        glyphMesh.userData.isGlyph = true;
        container.add(glyphMesh);
      }
    } catch (e) {
      console.warn('Failed to create icon glyph:', e);
    }
  }

  // Title text (Lora serif, bold)
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      const titleMesh = ctx.fontAtlas.createTextMesh({
        text: data.title,
        font: 'Lora',
        size: 20,
        weight: 600,
        color: colors.paper,
        emissive: 0x000000
      });

      if (titleMesh) {
        titleMesh.position.set(0, height / 2 - 0.75, 0.02);
        container.add(titleMesh);
      }
    } catch (e) {
      console.warn('Failed to create title mesh:', e);
    }
  }

  // Body text (JetBrains Mono, regular)
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      const bodyMesh = ctx.fontAtlas.createTextMesh({
        text: data.body,
        font: 'JetBrains Mono',
        size: 13,
        weight: 400,
        color: colors.paper,
        emissive: 0x000000
      });

      if (bodyMesh) {
        bodyMesh.position.set(0, height / 2 - 1.25, 0.02);
        container.add(bodyMesh);
      }
    } catch (e) {
      console.warn('Failed to create body mesh:', e);
    }
  }

  return container;
}
